static void compute_field_camera(const PalLoadedMap *m, int px, int py, float *out_cx, float *out_cy) {
    int cx = px - 304, cy = py - 240;
    if (m->w_px > 640) {
        if (cx < 0) cx = 0;
        if (cx > m->w_px - 640) cx = m->w_px - 640;
    } else {
        cx = -(640 - m->w_px) / 2;
    }
    if (m->h_px > 480) {
        if (cy < 0) cy = 0;
        if (cy > m->h_px - 480) cy = m->h_px - 480;
    } else {
        cy = -(480 - m->h_px) / 2;
    }
    if (out_cx) *out_cx = (float)cx;
    if (out_cy) *out_cy = (float)cy;
}

static int pal_path_resolve_slot(
    const PalGameDatabase *db, uint16_t ai_id,
    const uint8_t **out_code, uint32_t *out_code_len, uint32_t *out_entry_off
) {
    if (!db || ai_id == 0u) return -1;
    uint32_t bank = 0u, slot = 0u;
    if (ai_id < 2001u) {
        bank = 0u;
        slot = ai_id;
    } else {
        uint32_t rel = (uint32_t)ai_id - 2000u;
        bank = 1u + rel / 300u;
        slot = rel % 300u;
        if (slot == 0u && bank > 0u) {
            slot = 300u;
            bank--;
        }
    }
    if (bank >= 10u || !db->path_banks[bank] || db->path_bank_sizes[bank] <= PAL_MZ_HEADER_SIZE + 4u) {
        return -1;
    }
    const uint8_t *code = db->path_banks[bank] + PAL_MZ_HEADER_SIZE;
    size_t clen = db->path_bank_sizes[bank] - PAL_MZ_HEADER_SIZE;
    if ((size_t)slot * 4u + 4u > clen) return -1;
    uint32_t entry_off = rd_u32(code + (size_t)slot * 4u);
    if (entry_off == 0xFFFFFFFFu || (size_t)entry_off >= clen) return -1;
    if (out_code) *out_code = code;
    if (out_code_len) *out_code_len = (uint32_t)clen;
    if (out_entry_off) *out_entry_off = entry_off;
    return 0;
}

static int pal_npc_step_toward(
    PalFieldActor *a, const PalLoadedMap *map, const char *game_dir,
    int target_px, int target_py, int step_px
) {
    if (!a || step_px <= 0) return -1;
    int dx = target_px - a->px;
    int dy = target_py - a->py;
    if (abs(dx) <= 4 && abs(dy) <= 4) {
        if (!map || pal_map_can_stand_px(map, target_px, target_py, 2, 0)) {
            a->px = target_px;
            a->py = target_py;
        }
        a->ai_stall_ticks = 0;
        return 1;
    }
    int mdx = (dx > 0) ? (dx < step_px ? dx : step_px) : (-dx < step_px ? dx : -step_px);
    int mdy = (dy > 0) ? (dy < step_px ? dy : step_px) : (-dy < step_px ? dy : -step_px);
    int ndir = dir_from_delta(dx, dy, a->dir);
    int nx = a->px + mdx, ny = a->py + mdy;
    int moved = 0;
    if (!map || pal_map_can_stand_px(map, nx, ny, 2, 0)) {
        a->px = nx; a->py = ny; moved = 1;
    } else if (map && (abs(dx) > 24 || abs(dy) > 24)) {
        int path_tx[16], path_ty[16];
        int plen = pal_map_find_path_astar(map, a->px >> 4, a->py >> 4, target_px >> 4, target_py >> 4,
                                           2, path_tx, path_ty, 16);
        if (plen > 0) {
            int wdx = (path_tx[0] << 4) - a->px;
            int wdy = (path_ty[0] << 4) - a->py;
            int wmx = (wdx > 0) ? (wdx < step_px ? wdx : step_px) : (-wdx < step_px ? wdx : -step_px);
            int wmy = (wdy > 0) ? (wdy < step_px ? wdy : step_px) : (-wdy < step_px ? wdy : -step_px);
            if (pal_map_can_stand_px(map, a->px + wmx, a->py + wmy, 2, 0)) {
                ndir = dir_from_delta(wdx, wdy, a->dir);
                a->px += wmx; a->py += wmy; moved = 1;
            }
        }
    }
    if (!moved && map) {
        if (mdx != 0 && pal_map_can_stand_px(map, a->px + mdx, a->py, 2, 0)) {
            a->px += mdx; moved = 1;
        } else if (mdy != 0 && pal_map_can_stand_px(map, a->px, a->py + mdy, 2, 0)) {
            a->py += mdy; moved = 1;
        }
    }
    if (moved) {
        a->dir = ndir;
        a->ai_stall_ticks = 0;
        if (game_dir && a->act_id > 0u) {
            field_actor_set_sub(a, game_dir, a->act_id, (int)a->orig_sub_state + (a->dir & 7), 1);
        }
        return 0;
    }
    if (a->ai_stall_ticks < 250) a->ai_stall_ticks++;
    return -1;
}

static void pal_npc_ai_step(
    PalFieldActor *a, const PalLoadedMap *map, PalTalkWorldState *ws, const char *game_dir,
    const PalFieldActor *party, PalFieldActor *npcs, int npc_cnt
) {
    static uint32_t s_ai_rng = 0x5A17D201u;
    if (!a || !a->active || a->script_moving || !ws) return;
    int repel = (ws->story_flags[3002] != 0u) ? 1 : 0;
    int attract = (ws->story_flags[3003] != 0u) ? 1 : 0;

    if (a->ai_script_id == 0u) {
        if ((a->npc_flags & 0x2000u) == 0u || a->sight <= 0) return;
        int chased = 0;
        if (party && ws->combat_cooldown_ticks == 0 && !repel && !(a->aggro & 0x80u) && !pal_test_runtime_no_encounter()) {
            int dx = party[0].px - a->px;
            int dy = party[0].py - a->py;
            int lim = (int)a->sight * 16;
            if (attract) lim *= 2;
            if (dx * dx + dy * dy <= lim * lim) {
                pal_npc_step_toward(a, map, game_dir, party[0].px, party[0].py, 3);
                chased = 1;
            }
        }
        if (!chased && (a->px != (a->home_tx << 4) || a->py != (a->home_ty << 4))) {
            pal_npc_step_toward(a, map, game_dir, a->home_tx << 4, a->home_ty << 4, 2);
        }
        return;
    }

    if (!ws->db) return;
    for (int budget = 0; budget < 64 && a->ai_script_id > 0u; budget++) {
        const uint8_t *code = NULL;
        uint32_t clen = 0u, entry_off = 0u;
        if (pal_path_resolve_slot(ws->db, a->ai_script_id, &code, &clen, &entry_off) != 0) {
            a->ai_script_id = 0u;
            return;
        }
        a->ai_entry_off = entry_off;
        int64_t pos = (int64_t)entry_off + (int64_t)a->ai_pc * 2;
        if (pos < 0 || (uint64_t)(pos + 2) > (uint64_t)clen) {
            a->ai_pc = 0;
            return;
        }
        uint16_t op = rd_u16(code + pos);
        #define AI_HAS_W(k) (pos + (int64_t)((k) + 1) * 2 <= (int64_t)clen)
        #define AI_U16(k)   rd_u16(code + pos + (int64_t)(k) * 2)
        #define AI_U32(k)   rd_u32(code + pos + (int64_t)(k) * 2)
        #define AI_JUMP(t)  do { \
            uint32_t _toff = (t); \
            if (_toff >= clen) { a->ai_script_id = 0u; return; } \
            a->ai_pc = (int32_t)(((int64_t)_toff - (int64_t)entry_off) / 2); \
        } while (0)

        switch (op) {
            case 0:
                if (!a->active) {
                    a->ai_script_id = 0u;
                    return;
                }
                a->ai_pc = 0;
                return;
            case 1:
                a->ai_script_id = 0u;
                return;
            case 2:
                if (!AI_HAS_W(1)) { a->ai_script_id = 0u; return; }
                a->orig_sub_state = AI_U16(1);
                if (game_dir && a->act_id > 0u) {
                    field_actor_set_sub(a, game_dir, a->act_id, (int)a->orig_sub_state + (a->dir & 7), 1);
                }
                a->ai_pc += 2;
                break;
            case 3:
                if (!AI_HAS_W(1)) { a->ai_script_id = 0u; return; }
                a->dir = (int)(AI_U16(1) & 7u);
                if (game_dir && a->act_id > 0u) {
                    field_actor_set_sub(a, game_dir, a->act_id, (int)a->orig_sub_state + (a->dir & 7), 1);
                }
                a->ai_pc += 2;
                break;
            case 4:
                if (!AI_HAS_W(1)) { a->ai_script_id = 0u; return; }
                a->ai_wait_ticks = (int16_t)AI_U16(1);
                a->ai_pc += 2;
                break;
            case 5:
            case 6:
                if (a->ai_wait_ticks > 0) {
                    a->ai_wait_ticks--;
                    return;
                }
                a->ai_pc += 1;
                break;
            case 7:
                if (!AI_HAS_W(2)) { a->ai_script_id = 0u; return; }
                a->ai_target_tx = (int16_t)AI_U16(1);
                a->ai_target_ty = (int16_t)AI_U16(2);
                a->ai_stall_ticks = 0;
                a->ai_pc += 3;
                break;
            case 8: {
                if (map && map->w_tiles > 0 && map->h_tiles > 0 &&
                    (a->ai_target_tx < 0 || a->ai_target_ty < 0 ||
                     a->ai_target_tx >= map->w_tiles || a->ai_target_ty >= map->h_tiles)) {
                    a->ai_script_id = 0u;
                    return;
                }
                int st = pal_npc_step_toward(a, NULL, game_dir, (int)a->ai_target_tx << 4, (int)a->ai_target_ty << 4, 2);
                if (st == 1 || a->ai_stall_ticks >= 12) {
                    a->ai_stall_ticks = 0;
                    a->ai_pc += 1;
                }
                return;
            }
            case 9:
                if (!AI_HAS_W(1)) { a->ai_script_id = 0u; return; }
                a->ai_pc += 2;
                break;
            case 10:
                if (!AI_HAS_W(3)) { a->ai_script_id = 0u; return; }
                a->ai_pc += 4;
                break;
            case 11:
                if (!AI_HAS_W(1)) { a->ai_script_id = 0u; return; }
                a->ai_pc += 2;
                break;
            case 12:
                if (!AI_HAS_W(2)) { a->ai_script_id = 0u; return; }
                AI_JUMP(AI_U32(1));
                break;
            case 13: {
                if (!AI_HAS_W(3)) { a->ai_script_id = 0u; return; }
                uint16_t fl = AI_U16(1);
                int set = (fl < PAL_STORY_FLAG_CAP && ws->story_flags[fl] != 0u);
                if (set) AI_JUMP(AI_U32(2));
                else a->ai_pc += 4;
                break;
            }
            case 14: {
                if (!AI_HAS_W(3)) { a->ai_script_id = 0u; return; }
                uint16_t fl = AI_U16(1);
                int clr = (fl >= PAL_STORY_FLAG_CAP || ws->story_flags[fl] == 0u);
                if (clr) AI_JUMP(AI_U32(2));
                else a->ai_pc += 4;
                break;
            }
            case 15:
            case 16: {
                int32_t k = 1;
                int all_set = 1, any_set = 0;
                while (k < 64 && AI_HAS_W(k)) {
                    uint16_t fl = AI_U16(k);
                    k++;
                    if (fl == 0xFFFFu) break;
                    int is_set = (fl < PAL_STORY_FLAG_CAP && ws->story_flags[fl] != 0u);
                    if (is_set) any_set = 1;
                    else all_set = 0;
                }
                if (!AI_HAS_W(k + 1)) { a->ai_script_id = 0u; return; }
                int take = (op == 15) ? all_set : any_set;
                if (take) AI_JUMP(AI_U32(k));
                else a->ai_pc += k + 2;
                break;
            }
            case 17: {
                if (!AI_HAS_W(1)) { a->ai_script_id = 0u; return; }
                uint16_t fl = AI_U16(1);
                if (fl < PAL_STORY_FLAG_CAP) ws->story_flags[fl] = 1u;
                a->ai_pc += 2;
                break;
            }
            case 18: {
                if (!AI_HAS_W(1)) { a->ai_script_id = 0u; return; }
                uint16_t fl = AI_U16(1);
                if (fl < PAL_STORY_FLAG_CAP) ws->story_flags[fl] = 0u;
                a->ai_pc += 2;
                break;
            }
            case 19:
            case 20: {
                if (!AI_HAS_W(2)) { a->ai_script_id = 0u; return; }
                uint16_t v = AI_U16(1);
                int16_t val = (int16_t)AI_U16(2);
                if (v < PAL_SCRIPT_VAR_CAP) {
                    if (op == 19) ws->script_vars[v] = val;
                    else ws->script_vars[v] += val;
                }
                a->ai_pc += 3;
                break;
            }
            case 21:
            case 22:
            case 23: {
                if (!AI_HAS_W(4)) { a->ai_script_id = 0u; return; }
                uint16_t v = AI_U16(1);
                int16_t val = (int16_t)AI_U16(2);
                int32_t cur = (v < PAL_SCRIPT_VAR_CAP) ? ws->script_vars[v] : 0;
                int take = (op == 21) ? (cur == val) : (op == 22 ? (cur >= val) : (cur <= val));
                if (take) AI_JUMP(AI_U32(3));
                else a->ai_pc += 5;
                break;
            }
            case 24: {
                if (!AI_HAS_W(2)) { a->ai_script_id = 0u; return; }
                uint16_t obj = AI_U16(1);
                uint16_t nai = AI_U16(2);
                uint16_t eff_obj = (obj == 0xFFF0u) ? a->obj_id : obj;
                if (eff_obj < PAL_OBJ_CAP) {
                    ws->npc_ai_override[eff_obj] = (nai == 0u) ? 0xFFFFu : nai;
                }
                PalFieldActor *tgt = (obj == 0xFFF0u) ? a : talk_find_actor_by_obj(ws, NULL, npcs, npc_cnt, obj, NULL);
                if (tgt) {
                    tgt->ai_script_id = nai;
                    tgt->ai_pc = 0;
                    tgt->ai_wait_ticks = 0;
                    tgt->ai_stall_ticks = 0;
                    if (nai == 0u && map && eff_obj < PAL_OBJ_CAP) {
                        ws->npc_pos_map[eff_obj] = (uint16_t)map->map_id;
                        ws->npc_pos_tx[eff_obj] = (int16_t)(tgt->px >> 4);
                        ws->npc_pos_ty[eff_obj] = (int16_t)(tgt->py >> 4);
                        ws->npc_dir_override[eff_obj] = (int8_t)((tgt->dir & 7) + 1);
                        ws->npc_sub_override[eff_obj] = (uint16_t)(tgt->orig_sub_state + 1u);
                    }
                    if (tgt == a && nai > 0u) continue;
                }
                a->ai_pc += 3;
                break;
            }
            case 27:
            case 28: {
                if (!AI_HAS_W(1)) { a->ai_script_id = 0u; return; }
                uint16_t obj = AI_U16(1);
                PalFieldActor *tgt = (obj == 0xFFF0u) ? a : talk_find_actor_by_obj(ws, NULL, npcs, npc_cnt, obj, NULL);
                if (tgt) tgt->active = (op == 28) ? 1 : 0;
                if (obj < PAL_OBJ_CAP && obj != 0xFFF0u) {
                    ws->npc_visibility_override[obj] = (op == 28) ? 1u : 2u;
                }
                if (op == 28 && tgt && tgt->active && tgt->act_id == 700u && (tgt->npc_flags & 0x20u) != 0u && tgt->talk_id > 0u) {
                    ws->auto_trig_recheck = 1;
                }
                a->ai_pc += 2;
                break;
            }
            case 29:
            case 49: {
                if (!AI_HAS_W(2)) { a->ai_script_id = 0u; return; }
                int16_t tx = (int16_t)AI_U16(1);
                int16_t ty = (int16_t)AI_U16(2);
                if (op == 29) {
                    a->px = (int)tx << 4;
                    a->py = (int)ty << 4;
                } else {
                    a->px += (int)tx << 4;
                    a->py += (int)ty << 4;
                }
                a->ai_pc += 3;
                break;
            }
            case 30: {
                static const int kDx[8] = {0, 0, -2, 2, -2, 2, -2, 2};
                static const int kDy[8] = {-2, 2, 0, 0, -2, 2, 2, -2};
                if ((a->npc_flags & 0x2000u) != 0u && a->sight > 0 && party && ws->combat_cooldown_ticks == 0 && !repel && !(a->aggro & 0x80u)) {
                    int pdx = party[0].px - a->px;
                    int pdy = party[0].py - a->py;
                    int lim = (int)a->sight * 16;
                    if (attract) lim *= 2;
                    if (pdx * pdx + pdy * pdy <= lim * lim) {
                        pal_npc_step_toward(a, map, game_dir, party[0].px, party[0].py, 3);
                        a->ai_pc += 1;
                        return;
                    }
                }
                if (a->ai_wander_rem == 0u) {
                    s_ai_rng = s_ai_rng * 1664525u + 1013904223u;
                    a->ai_wander_dir = (uint8_t)((s_ai_rng >> 16) & 7u);
                    a->ai_wander_rem = (uint8_t)(4u + ((s_ai_rng >> 8) % 7u));
                }
                int d = (int)(a->ai_wander_dir & 7u);
                int nx = a->px + kDx[d];
                int ny = a->py + kDy[d];
                int home_px = (int)a->home_tx << 4;
                int home_py = (int)a->home_ty << 4;
                if (abs(nx - home_px) <= 80 && abs(ny - home_py) <= 80 &&
                    (!map || pal_map_can_stand_px(map, nx, ny, 2, 0))) {
                    a->px = nx;
                    a->py = ny;
                    a->dir = d;
                    if (game_dir && a->act_id > 0u) {
                        field_actor_set_sub(a, game_dir, a->act_id, (int)a->orig_sub_state + (a->dir & 7), 1);
                    }
                    a->ai_wander_rem--;
                } else {
                    a->ai_wander_rem = 0u;
                }
                if (a->ai_wander_rem == 0u) a->ai_pc += 1;
                return;
            }
            case 31: {
                if (!AI_HAS_W(3)) { a->ai_script_id = 0u; return; }
                uint16_t nact = AI_U16(1);
                uint16_t nsub = AI_U16(2);
                uint16_t ndir = AI_U16(3);
                if (nact != 0xFFFFu) a->act_id = nact;
                if (nsub != 0xFFFFu) a->orig_sub_state = nsub;
                if (ndir != 0xFFFFu) a->dir = (int)(ndir & 7u);
                if (game_dir && a->act_id > 0u) {
                    field_actor_set_sub(a, game_dir, a->act_id, (int)a->orig_sub_state + (a->dir & 7), 1);
                }
                a->ai_pc += 4;
                break;
            }
            case 32:
                if (!AI_HAS_W(1)) { a->ai_script_id = 0u; return; }
                a->ai_pc += 2;
                break;
            case 33:
            case 36: {
                int wcnt = (op == 36) ? 4 : 2;
                if (!AI_HAS_W(wcnt - 1)) { a->ai_script_id = 0u; return; }
                uint16_t obj = AI_U16(1);
                int ox = (op == 36) ? ((int)(int16_t)AI_U16(2) << 4) : 0;
                int oy = (op == 36) ? ((int)(int16_t)AI_U16(3) << 4) : 0;
                if ((obj == 0xFFF1u || obj == 0xFFFEu) && (ws->combat_cooldown_ticks > 0 || repel)) {
                    a->ai_stall_ticks = 0;
                    a->ai_pc += wcnt;
                    break;
                }
                const PalFieldActor *tgt = NULL;
                if ((obj == 0xFFF1u || obj == 0xFFFEu) && party) tgt = &party[0];
                else if (obj == 0xFFF0u) tgt = a;
                else tgt = talk_find_actor_by_obj(ws, NULL, npcs, npc_cnt, obj, NULL);
                if (!tgt) {
                    a->ai_pc += wcnt;
                    break;
                }
                int st = pal_npc_step_toward(a, map, game_dir, tgt->px + ox, tgt->py + oy, 3);
                if (st == 1 || a->ai_stall_ticks >= 10) {
                    a->ai_stall_ticks = 0;
                    a->ai_pc += wcnt;
                }
                return;
            }
            case 34: {
                if (!AI_HAS_W(1)) { a->ai_script_id = 0u; return; }
                int64_t q = pos + 4;
                int64_t found_end = -1;
                while (q + 1 < (int64_t)clen) {
                    if (code[q] == 0x25u && code[q + 1] == 0x51u) {
                        found_end = q + 2;
                        break;
                    }
                    q++;
                }
                if (found_end < 0 || ((found_end - (int64_t)entry_off) & 1) != 0) {
                    a->ai_script_id = 0u;
                    return;
                }
                a->ai_pc = (int32_t)((found_end - (int64_t)entry_off) / 2);
                break;
            }
            case 35:
                a->ai_pc += 1;
                break;
            case 37:
            case 45: {
                if (!AI_HAS_W(4)) { a->ai_script_id = 0u; return; }
                uint16_t obj = AI_U16(1);
                int dist_px = (int)AI_U16(2) * 16;
                uint32_t toff = AI_U32(3);
                int in_range = 0;
                int is_party_tgt = (obj == 0xFFF1u || obj == 0xFFFEu) ? 1 : 0;
                if (!(is_party_tgt && (ws->combat_cooldown_ticks > 0 || repel || (a->aggro & 0x80u)))) {
                    if (is_party_tgt && attract) dist_px *= 2;
                    const PalFieldActor *tgt = NULL;
                    if (is_party_tgt && party) tgt = &party[0];
                    else if (obj == 0xFFF0u) tgt = a;
                    else tgt = talk_find_actor_by_obj(ws, NULL, npcs, npc_cnt, obj, NULL);
                    if (tgt && tgt->active) {
                        int64_t dx = (int64_t)tgt->px - (int64_t)a->px;
                        int64_t dy = (int64_t)tgt->py - (int64_t)a->py;
                        in_range = (dx * dx + dy * dy <= (int64_t)dist_px * (int64_t)dist_px) ? 1 : 0;
                    }
                }
                int take = (op == 37) ? in_range : !in_range;
                if (take) AI_JUMP(toff);
                else a->ai_pc += 5;
                break;
            }
            case 39:
            case 40:
            case 41: {
                if (!AI_HAS_W(3)) { a->ai_script_id = 0u; return; }
                uint16_t raw_obj = AI_U16(1);
                uint16_t robj = (raw_obj == 0xFFF0u) ? a->obj_id : raw_obj;
                uint16_t rv = AI_U16(2);
                int16_t val = (int16_t)AI_U16(3);
                if (robj < PAL_OBJ_CAP && rv < 4u) {
                    if (op == 39) ws->obj_rv[robj][rv] = val;
                    else if (op == 40) ws->obj_rv[robj][rv] = (int16_t)(ws->obj_rv[robj][rv] + val);
                    else ws->obj_rv[robj][rv] = (int16_t)(ws->obj_rv[robj][rv] - val);
                }
                a->ai_pc += 4;
                break;
            }
            case 42:
            case 43:
            case 44: {
                if (!AI_HAS_W(5)) { a->ai_script_id = 0u; return; }
                uint16_t raw_obj = AI_U16(1);
                uint16_t robj = (raw_obj == 0xFFF0u) ? a->obj_id : raw_obj;
                uint16_t rv = AI_U16(2);
                int16_t val = (int16_t)AI_U16(3);
                uint32_t toff = AI_U32(4);
                int16_t cur = (robj < PAL_OBJ_CAP && rv < 4u) ? ws->obj_rv[robj][rv] : 0;
                int take = (op == 42) ? (cur < val) : (op == 43 ? (cur == val) : (cur > val));
                if (take) AI_JUMP(toff);
                else a->ai_pc += 6;
                break;
            }
            case 0xFFFFu:
            default:
                a->ai_script_id = 0u;
                return;
        }
        #undef AI_HAS_W
        #undef AI_U16
        #undef AI_U32
        #undef AI_JUMP
    }
}

static void step_script_moving_actor(PalFieldActor *a, const char *game_dir, int is_party, int rem_ticks) {
    if (!a || !a->script_moving) return;
    int dx = a->walk_target_px - a->px;
    int dy = a->walk_target_py - a->py;
    if (dx == 0 && dy == 0) {
        a->script_moving = 0;
        int stand_base = pal_actor_move_sub_base(a, is_party, 0);
        field_actor_set_sub(a, game_dir, a->act_id, stand_base + (a->dir & 7), (is_party && stand_base == 0) ? 0 : 1);
        return;
    }
    int step = (a->custom_speed_px > 0) ? a->custom_speed_px : 4;
    if (rem_ticks > 0 && a->custom_speed_px == 0) {
        int mdist = abs(dx) > abs(dy) ? abs(dx) : abs(dy);
        int need = (mdist + rem_ticks - 1) / rem_ticks;
        if (need > step) step = need;
    }
    if (abs(dx) <= step) a->px = a->walk_target_px;
    else a->px += (dx > 0 ? step : -step);
    if (abs(dy) <= step) a->py = a->walk_target_py;
    else a->py += (dy > 0 ? step : -step);
    if (a->px == a->walk_target_px && a->py == a->walk_target_py) {
        a->script_moving = 0;
        int stand_base = pal_actor_move_sub_base(a, is_party, 0);
        field_actor_set_sub(a, game_dir, a->act_id, stand_base + (a->dir & 7), (is_party && stand_base == 0) ? 0 : 1);
    }
}

static const char *pal_resolve_map_bgm(const PalTalkWorldState *ws, const PalLoadedMap *map) {
    if (ws && map && map->map_id < PAL_MAP_BGM_OVERRIDE_CAP) {
        uint16_t ov = ws->map_bgm_override[map->map_id];
        if (ov > 0u && ov < 64u && ws->db && ws->db->bgm_tracks[ov][0] != '\0') {
            return ws->db->bgm_tracks[ov];
        }
    }
    return map ? map->bgm_track : "";
}

static void combat_set_hero_victory_pose(PalCombatState *cb, const PalTalkWorldState *ws, int hidx) {
    if (!cb || !ws || !cb->game_dir[0] || hidx < 0 || hidx >= ws->party_member_count || hidx >= 4) return;
    const PalPartyMemberState *m = &ws->party_members[hidx];
    if (!m->active) return;
    uint32_t hact = pal_hero_battle_act_id(m->hero_id);
    static const int32_t kVictoryPrefs[4] = {36, 35, 33, 1};
    PalActVM vm = {0};
    if (pal_act_vm_init_with_prefs(cb->game_dir, "all_char.act", hact, kVictoryPrefs, 4, 1, &vm) == 0) {
        pal_act_warm_start(&vm, 1);
        vm.last_sfx_id = 0;
        cb->hero_vms[hidx] = vm;
        cb->hero_vm_ok[hidx] = 1;
    }
}

static int combat_find_next_levelup_hero(const PalCombatState *cb, int start_idx) {
    if (!cb) return -1;
    for (int p = (start_idx < 0 ? 0 : start_idx); p < 4; p++) {
        if (cb->hero_levelups[p].leveled_up) return p;
    }
    return -1;
}

static int combat_advance_settlement(
    PalCombatState *cb, const PalTalkWorldState *ws, const char *game_dir,
    PalSfxPool *sfx_pool, float sfx_vol, int runtime_mute
) {
    if (!cb) return 1;
    if (cb->phase == COMBAT_PHASE_FLED) return 1;
    if (cb->phase == COMBAT_PHASE_DEFEAT) {
        if (cb->defeat_stage == 0) {
            cb->defeat_stage = 1;
            cb->dirty = 1;
            return 0;
        }
        return 1;
    }
    if (cb->phase != COMBAT_PHASE_VICTORY) return 1;

    if (cb->settle_stage == 0) {
        if (cb->drop_item_count > 0) {
            cb->settle_stage = 1;
            cb->settle_sub_idx = 0;
            cb->dirty = 1;
            if (sfx_pool && game_dir) play_ui_sfx(game_dir, 55u, sfx_pool, sfx_vol, runtime_mute);
            return 0;
        }
        int nh = combat_find_next_levelup_hero(cb, 0);
        if (nh >= 0) {
            cb->settle_stage = 2;
            cb->settle_hero_idx = nh;
            cb->settle_magic_idx = 0;
            cb->dirty = 1;
            combat_set_hero_victory_pose(cb, ws, nh);
            if (sfx_pool && game_dir) play_ui_sfx(game_dir, 57u, sfx_pool, sfx_vol, runtime_mute);
            return 0;
        }
        return 1;
    }

    if (cb->settle_stage == 1) {
        cb->settle_sub_idx++;
        if (cb->settle_sub_idx < cb->drop_item_count) {
            cb->dirty = 1;
            if (sfx_pool && game_dir) play_ui_sfx(game_dir, 55u, sfx_pool, sfx_vol, runtime_mute);
            return 0;
        }
        int nh = combat_find_next_levelup_hero(cb, 0);
        if (nh >= 0) {
            cb->settle_stage = 2;
            cb->settle_hero_idx = nh;
            cb->settle_magic_idx = 0;
            cb->dirty = 1;
            combat_set_hero_victory_pose(cb, ws, nh);
            if (sfx_pool && game_dir) play_ui_sfx(game_dir, 57u, sfx_pool, sfx_vol, runtime_mute);
            return 0;
        }
        return 1;
    }

    if (cb->settle_stage == 2) {
        if (cb->settle_hero_idx >= 0 && cb->settle_hero_idx < 4 &&
            cb->hero_levelups[cb->settle_hero_idx].learned_magic_count > 0) {
            cb->settle_stage = 3;
            cb->settle_magic_idx = 0;
            cb->dirty = 1;
            if (sfx_pool && game_dir) play_ui_sfx(game_dir, 55u, sfx_pool, sfx_vol, runtime_mute);
            return 0;
        }
        int nh = combat_find_next_levelup_hero(cb, cb->settle_hero_idx + 1);
        if (nh >= 0) {
            cb->settle_stage = 2;
            cb->settle_hero_idx = nh;
            cb->settle_magic_idx = 0;
            cb->dirty = 1;
            combat_set_hero_victory_pose(cb, ws, nh);
            if (sfx_pool && game_dir) play_ui_sfx(game_dir, 57u, sfx_pool, sfx_vol, runtime_mute);
            return 0;
        }
        return 1;
    }

    if (cb->settle_stage == 3) {
        cb->settle_magic_idx++;
        if (cb->settle_hero_idx >= 0 && cb->settle_hero_idx < 4 &&
            cb->settle_magic_idx < cb->hero_levelups[cb->settle_hero_idx].learned_magic_count) {
            cb->dirty = 1;
            if (sfx_pool && game_dir) play_ui_sfx(game_dir, 55u, sfx_pool, sfx_vol, runtime_mute);
            return 0;
        }
        int nh = combat_find_next_levelup_hero(cb, cb->settle_hero_idx + 1);
        if (nh >= 0) {
            cb->settle_stage = 2;
            cb->settle_hero_idx = nh;
            cb->settle_magic_idx = 0;
            cb->dirty = 1;
            combat_set_hero_victory_pose(cb, ws, nh);
            if (sfx_pool && game_dir) play_ui_sfx(game_dir, 57u, sfx_pool, sfx_vol, runtime_mute);
            return 0;
        }
        return 1;
    }

    return 1;
}

static void combat_finish_to_field(
    const PalLaunchConfig *cfg, PalCombatState *combat_state, PalTalkWorldState *world_state,
    PalTalkVM *talk_vm, PalLoadedMap *map, PalFieldActor *party, PalFieldActor *npcs, int *io_npc_cnt, int npc_cap,
    PalCampMenuState *camp_menu, PalBgmPlayer *bgm, PalSfxPool *sfx_pool,
    float bgm_vol, float sfx_vol, int runtime_mute,
    PalSceneState *scene, int *pending_fade_in_ms, char *cur_bgm_playing, size_t bgm_cap, Uint64 *last_ns
) {
    int npc_cnt = io_npc_cnt ? *io_npc_cnt : 0;
    play_ui_sfx(cfg->game_dir, 2u, sfx_pool, sfx_vol, runtime_mute);
    int won = (combat_state->phase == COMBAT_PHASE_VICTORY) ? 1 : 0;
    int defeated = (combat_state->phase == COMBAT_PHASE_DEFEAT) ? 1 : 0;
    int fled = (combat_state->phase == COMBAT_PHASE_FLED) ? 1 : 0;
    combat_cleanup_battle_end(combat_state, world_state, won);
    if (!won && world_state) {
        for (int p = 0; p < world_state->party_member_count && p < 4; p++) {
            PalPartyMemberState *m = &world_state->party_members[p];
            if (!m->active) continue;
            if (defeated) {
                m->cur_hp = m->eff_max_hp;
                m->cur_mp = m->eff_max_mp;
            } else if (m->cur_hp <= 0) {
                m->cur_hp = 1;
            }
        }
    }
    if (world_state) {
        world_state->combat_cooldown_ticks = (!won || fled) ? 90 : 30;
    }
    *scene = PAL_SCENE_FIELD;
    camp_menu->dirty = 1;
    *pending_fade_in_ms = 140;
    pal_bgm_set_duck(bgm, 1.0f);
    const char *field_bgm = pal_resolve_map_bgm(world_state, map);
    pal_bgm_play_track(bgm, cfg->game_dir, field_bgm, bgm_vol, runtime_mute);
    snprintf(cur_bgm_playing, bgm_cap, "%s", field_bgm);

    if (talk_vm->active && talk_vm->paused_for_battle) {
        talk_vm->paused_for_battle = 0;
        if (world_state) world_state->story_flags[3001] = won ? 1u : 0u;
        if (won && talk_vm->talk_id >= 5001 && talk_vm->talk_id <= 5999) {
            PalFieldActor *m = talk_find_actor_by_obj(world_state, NULL, npcs, npc_cnt, talk_vm->trigger_obj_id, NULL);
            if (m) m->active = 0;
            if (world_state && talk_vm->trigger_obj_id < PAL_OBJ_CAP) {
                world_state->npc_visibility_override[talk_vm->trigger_obj_id] = 2u;
            }
        }
        pal_talk_vm_step_ex(talk_vm, world_state, cfg->game_dir, map->map_id, party, npcs, io_npc_cnt, npc_cap, 0);
    }
    *last_ns = SDL_GetTicksNS();
}

